custom_css:
/* =========================================================
   MANIC PIXIE DREAM GIRL — SILLYTAVERN LIGHT THEME
   Cleaned and consolidated from Vintage Planner v1.2.
   ========================================================= */

:root {
    --vp-paper: #f8f1e8;
    --vp-paper-2: #f2e7da;
    --vp-paper-3: #eadccc;
    --vp-paper-light: #fffaf3;

    --vp-ink: #542c2e;
    --vp-ink-soft: #79585a;
    --vp-line: rgba(84, 44, 46, 0.34);
    --vp-line-soft: rgba(84, 44, 46, 0.16);

    --vp-yellow: #eac955;
    --vp-pink: #dfa2bd;
    --vp-orange: #eeae4f;
    --vp-lilac: #b59bd8;
    --vp-blue: #9fbfd0;
    --vp-green: #a9be67;
    --vp-coral: #e78677;

    --vp-serif: Georgia, "Times New Roman", serif;
    --vp-mono: ui-monospace, "Cascadia Mono", "Courier New", monospace;
    --vp-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;

    --vp-shadow-small: 2px 3px 0 rgba(84, 44, 46, 0.13);
    --vp-shadow-medium: 4px 6px 0 rgba(84, 44, 46, 0.13);
    --vp-shadow-float: 0 18px 55px rgba(51, 29, 30, 0.25);

    --top-bar-bg: rgba(248, 241, 232, 0.96);

    /* Paper-craft icon palette */
    --craft-brown: #754b4e;
    --craft-rose: #b96f7d;
    --craft-sage: #738c70;
    --craft-blue: #6b8996;
    --craft-mustard: #b28a49;
    --craft-icon-size: 1.08em;
    --craft-icon-shadow: rgba(84, 44, 46, 0.18);
}

/* =========================================================
   BACKGROUND + GLOBAL TYPE
   ========================================================= */

html,
body {
    color: var(--vp-ink) !important;
    font-family: var(--vp-serif);
}

body {
    background-color: var(--vp-paper) !important;
}

#bg1,
#bg_custom {
    position: fixed !important;
    inset: 0 !important;
    overflow: hidden !important;
}

#bg1::after,
#bg_custom::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;

    background:
        radial-gradient(circle at 14% 18%, rgba(223, 162, 189, 0.11) 0 1px, transparent 1.7px) 0 0 / 17px 17px,
        radial-gradient(circle at 85% 78%, rgba(159, 191, 208, 0.15), transparent 33%),
        linear-gradient(rgba(248, 241, 232, 0.28), rgba(239, 227, 213, 0.48));
}

::selection {
    color: var(--vp-ink);
    background: rgba(234, 201, 85, 0.62);
}

a,
.link,
.textLink {
    color: #557e8f !important;
    text-decoration-color: rgba(85, 126, 143, 0.5);
    text-underline-offset: 3px;
}

a:hover,
.link:hover,
.textLink:hover {
    color: var(--vp-ink) !important;
    text-decoration-color: var(--vp-coral);
}

em,
i {
    color: var(--vp-ink-soft);
}

blockquote {
    margin: 0.8em 0;
    padding: 0.55em 0.9em;
    color: var(--vp-ink-soft);
    background: rgba(255, 255, 255, 0.28);
    border-left: 5px solid var(--vp-blue);
    border-radius: 0 7px 7px 0;
}

hr {
    height: 1px;
    border: 0;
    background: var(--vp-line);
}

/* WELCOME PAGE */

.welcomeHeaderLogo{
  content: url("https://files.catbox.moe/9b2wt9.png");
  width: auto !important;
  height: clamp(7em, 15vw, 11em) !important;
  object-fit: contain;
  margin: 12px auto;
  display: block;
}

.welcomeHeaderVersionDisplay {
  display: none !important;
}

/* =========================================================
   TOP BAR + DRAWERS — LAYOUT-SAFE
   ========================================================= */

/*
   IMPORTANT:
   SillyTavern calculates the top bar and side-drawer geometry from its own
   responsive variables and .fillLeft/.fillRight rules. This theme deliberately
   does not set height, width, position, top, left, right, margin, padding,
   overflow, transform, min/max size, or box-sizing on those elements.
*/

#top-bar,
#top-settings-holder,
#extensionTopBar,
#extensionConnectionProfiles {
    color: var(--vp-ink) !important;
    background-color: rgba(248, 241, 232, 0.96) !important;
    border-color: var(--vp-line) !important;
}

/* Only colors are themed on the actual panels. Native ST rules retain complete
   control of normal, pinned, maximized, movable, and mobile drawer layouts. */
#left-nav-panel,
#right-nav-panel {
    color: var(--vp-ink) !important;
    background-color: rgba(248, 241, 232, 0.98) !important;
}

/* Drawer icons are fully visible at rest and soften on hover. */

#top-bar .drawer-icon,
#top-settings-holder .drawer-icon,
#extensionTopBar .drawer-icon,
#extensionConnectionProfiles .drawer-icon,
.drawer-icon.closedIcon,
.drawer-icon.openIcon {
    color: var(--vp-ink) !important;
    opacity: 1 !important;
    filter: none !important;
    transition:
        opacity 0.12s ease,
        filter 0.12s ease,
        color 0.12s ease,
        background-color 0.12s ease !important;
}

/* Reverse the normal SillyTavern emphasis:
   hover is a little quieter than the resting state. */
#top-bar .drawer-icon:hover,
#top-settings-holder .drawer-icon:hover,
#extensionTopBar .drawer-icon:hover,
#extensionConnectionProfiles .drawer-icon:hover,
.drawer-icon.closedIcon:hover,
.drawer-icon.openIcon:hover {
    color: var(--vp-ink-soft) !important;
    opacity: 0.82 !important;
    filter: saturate(0.72) brightness(0.96) !important;
}

/* Keep currently open/active drawers fully legible. */
#top-bar .drawer-icon.openIcon,
#top-settings-holder .drawer-icon.openIcon,
#extensionTopBar .drawer-icon.openIcon,
#extensionConnectionProfiles .drawer-icon.openIcon {
    color: var(--vp-ink) !important;
    opacity: 1 !important;
    filter: none !important;
}

/* Preserve an obvious disabled state where one is explicitly supplied. */
#top-bar .drawer-icon:is(.disabled, [disabled], [aria-disabled="true"]),
#top-settings-holder .drawer-icon:is(.disabled, [disabled], [aria-disabled="true"]),
#extensionTopBar .drawer-icon:is(.disabled, [disabled], [aria-disabled="true"]),
#extensionConnectionProfiles .drawer-icon:is(.disabled, [disabled], [aria-disabled="true"]) {
    color: var(--vp-ink-soft) !important;
    opacity: 0.42 !important;
    filter: saturate(0.35) !important;
    cursor: default !important;
}

/* =========================================================
   SUBTLE SECONDARY DROPDOWN HEADERS
   A quiet fallback for extension and secondary collapsible sections.
   The more specific main-UI rules below keep their bold treatment.
   ========================================================= */

:where(.inline-drawer-toggle.inline-drawer-header) {
    color: var(--vp-ink-soft) !important;
    background:
        linear-gradient(
            90deg,
            rgba(159, 191, 208, 0.14),
            rgba(255, 250, 243, 0.30) 58%,
            rgba(223, 162, 189, 0.09)
        ) !important;
    border: 1px solid var(--vp-line-soft) !important;
    border-left-color: rgba(85, 126, 143, 0.48) !important;
    border-left-width: 3px !important;
    border-radius: 6px !important;
    box-shadow: 0 1px 0 rgba(84, 44, 46, 0.08);
    font-family: var(--vp-serif);
    font-size: 0.88rem;
    font-weight: 650;
    letter-spacing: 0.015em;
    text-transform: none;
    opacity: 0.96;
}

:where(.inline-drawer-toggle.inline-drawer-header):hover {
    color: var(--vp-ink) !important;
    background:
        linear-gradient(
            90deg,
            rgba(159, 191, 208, 0.20),
            rgba(255, 250, 243, 0.38) 56%,
            rgba(223, 162, 189, 0.14)
        ) !important;
    border-left-color: var(--vp-pink) !important;
}

/* =========================================================
   SUBTLE RESTORABLE SECTION HEADERS
   Used by preset titles and User Settings labels such as UI Theme and
   Custom CSS. These are section dividers, not collapsible controls.
   ========================================================= */

:where(.title_restorable),
#user-settings-block :is(
    [name="CharacterHandlingToggles"],
    [name="MiscellaneousToggles"],
    [name="ChatMessageHandlingToggles"],
    [name="STscriptToggles"]
) > h4 {
    color: var(--vp-ink) !important;
    background:
        linear-gradient(
            90deg,
            rgba(234, 201, 85, 0.15),
            rgba(255, 250, 243, 0.18) 58%,
            transparent 100%
        ) !important;
    border: 0 !important;
    border-left: 3px solid rgba(223, 162, 189, 0.62) !important;
    border-bottom: 1px solid var(--vp-line-soft) !important;
    border-radius: 3px 0 0 3px !important;
    box-shadow: none !important;
    padding: 0.28em 0.45em 0.28em 0.55em !important;
    font-family: var(--vp-serif) !important;
    font-size: 0.90rem !important;
    font-weight: 700 !important;
    letter-spacing: 0.025em !important;
    text-transform: none !important;
    opacity: 1 !important;
}

/* =========================================================
   MAIN-UI CONTROL SCOPE
   Keep the paper-craft treatment on native SillyTavern controls without
   overriding extension settings or independently mounted extension panels.
   ========================================================= */

@scope (
    #top-settings-holder > .drawer > .drawer-content:not(#rm_extensions_block),
    #floatingPrompt,
    #cfgConfig,
    #logprobsViewer,
    #form_sheld,
    #character_popup,
    #shadow_popup,
    dialog.popup,
    #character_context_menu,
    #completion_prompt_manager_popup
) {

/* =========================================================
   HEADERS + INLINE DRAWERS
   ========================================================= */

.inline-drawer,
.inline-drawer-content,
#user-settings-block {
    border-color: var(--vp-line-soft) !important;
}

.inline-drawer-content {
    background: rgba(255, 250, 243, 0.42) !important;
    border: 1px solid var(--vp-line-soft) !important;
    border-top: 0 !important;
    border-radius: 0 0 8px 8px !important;
}

.inline-drawer-toggle,
.inline-drawer-header,
#user-settings-block h4:not(.title_restorable),
.standoutHeader:not(.title_restorable),
h3.standoutHeader:not(.title_restorable) {
    color: var(--vp-ink) !important;
    background:
        linear-gradient(90deg, rgba(234, 201, 85, 0.22), rgba(255, 255, 255, 0.16) 38%, rgba(223, 162, 189, 0.12)) !important;
    border: 1.5px solid var(--vp-line) !important;
    border-radius: 8px !important;
    box-shadow: var(--vp-shadow-small);
    font-family: var(--vp-mono);
    font-size: 0.78rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    opacity: 1;
}

.inline-drawer-toggle:hover,
.inline-drawer-header:hover {
    background:
        linear-gradient(90deg, rgba(234, 201, 85, 0.32), rgba(255, 255, 255, 0.22) 38%, rgba(223, 162, 189, 0.2)) !important;
}

/* =========================================================
   INPUTS + SELECTS
   ========================================================= */

input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),
textarea,
select,
.text_pole,
.select2-container .select2-selection,
.select2-dropdown {
    color: var(--vp-ink) !important;
    background:
        linear-gradient(transparent 94%, rgba(84, 44, 46, 0.08) 94%) 0 0 / 100% 1.65em,
        rgba(255, 250, 243, 0.76) !important;
    border: 1.5px solid var(--vp-line) !important;
    border-radius: 7px !important;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.55);
    font-family: var(--vp-serif);
}

input::placeholder,
textarea::placeholder {
    color: rgba(121, 88, 90, 0.62) !important;
    font-style: italic;
}

input:focus,
textarea:focus,
select:focus,
.text_pole:focus,
.select2-container--focus .select2-selection {
    outline: none !important;
    border-color: var(--vp-ink) !important;
    box-shadow:
        0 0 0 3px rgba(234, 201, 85, 0.24),
        inset 0 1px 0 rgba(255, 255, 255, 0.55) !important;
}

select option {
    color: var(--vp-ink);
    background: var(--vp-paper-light);
}

/* Range controls */

input[type="range"],
input.neo-range-slider[type="range"] {
    background: rgba(255, 250, 243, 0.78) !important;
    border-color: rgba(84, 44, 46, 0.25) !important;
    box-shadow: inset 0 1px 2px rgba(84, 44, 46, 0.06) !important;
    filter: none !important;
    opacity: 1 !important;
    transition:
        background-color 0.14s ease,
        border-color 0.14s ease,
        box-shadow 0.14s ease !important;
}

input[type="range"]::-webkit-slider-thumb,
input.neo-range-slider[type="range"]::-webkit-slider-thumb {
    background: #efd3df !important;
    border-color: rgba(84, 44, 46, 0.48) !important;
    box-shadow: 1px 2px 0 rgba(84, 44, 46, 0.11) !important;
    transition:
        background-color 0.14s ease,
        border-color 0.14s ease,
        box-shadow 0.14s ease,
        transform 0.14s ease !important;
}

input[type="range"]::-moz-range-thumb,
input.neo-range-slider[type="range"]::-moz-range-thumb {
    background: #efd3df !important;
    border-color: rgba(84, 44, 46, 0.48) !important;
    box-shadow: 1px 2px 0 rgba(84, 44, 46, 0.11) !important;
    transition:
        background-color 0.14s ease,
        border-color 0.14s ease,
        box-shadow 0.14s ease,
        transform 0.14s ease !important;
}

/* Darker, richer hover state. */
input[type="range"]:not(:disabled):hover,
input.neo-range-slider[type="range"]:not(:disabled):hover {
    background: var(--vp-paper-3) !important;
    border-color: rgba(84, 44, 46, 0.52) !important;
    box-shadow: inset 0 1px 3px rgba(84, 44, 46, 0.12) !important;
}

input[type="range"]:not(:disabled):hover::-webkit-slider-thumb,
input.neo-range-slider[type="range"]:not(:disabled):hover::-webkit-slider-thumb {
    background: var(--vp-pink) !important;
    border-color: var(--vp-ink) !important;
    box-shadow: 2px 3px 0 rgba(84, 44, 46, 0.18) !important;
    transform: scale(1.06);
}

input[type="range"]:not(:disabled):hover::-moz-range-thumb,
input.neo-range-slider[type="range"]:not(:disabled):hover::-moz-range-thumb {
    background: var(--vp-pink) !important;
    border-color: var(--vp-ink) !important;
    box-shadow: 2px 3px 0 rgba(84, 44, 46, 0.18) !important;
    transform: scale(1.06);
}

/* Slightly stronger while dragging. */
input[type="range"]:not(:disabled):active::-webkit-slider-thumb,
input.neo-range-slider[type="range"]:not(:disabled):active::-webkit-slider-thumb {
    background: var(--vp-coral) !important;
    transform: scale(1.1);
}

input[type="range"]:not(:disabled):active::-moz-range-thumb,
input.neo-range-slider[type="range"]:not(:disabled):active::-moz-range-thumb {
    background: var(--vp-coral) !important;
    transform: scale(1.1);
}

/* Disabled sliders remain intentionally faded. */
input[type="range"]:disabled,
input.neo-range-slider[type="range"]:disabled {
    opacity: 0.46 !important;
    filter: saturate(0.35) !important;
    cursor: default !important;
}

/* Select2 multiselect chips */

.select2-container .select2-selection--multiple .select2-selection__choice,
.select2-selection__choice {
    color: var(--vp-ink) !important;
    background: rgba(159, 191, 208, 0.24) !important;
    border: 1px solid rgba(84, 44, 46, 0.34) !important;
    border-radius: 999px !important;
    box-shadow: 1px 2px 0 rgba(84, 44, 46, 0.10) !important;
    font-family: var(--vp-mono);
    font-size: 0.68rem !important;
    letter-spacing: 0.035em;
    opacity: 1 !important;
    filter: none !important;
}

/* The visible label inside the chip. */
.select2-selection__choice__display {
    color: var(--vp-ink) !important;
    background: transparent !important;
    opacity: 1 !important;
    filter: none !important;
    text-shadow: none !important;
}

/* Remove button on multi-select chips. */
.select2-selection__choice__remove {
    color: var(--vp-ink-soft) !important;
    background: transparent !important;
    border: 0 !important;
    opacity: 0.78 !important;
    filter: none !important;
}

.select2-selection__choice__remove:hover {
    color: var(--vp-ink) !important;
    background: rgba(223, 162, 189, 0.20) !important;
    opacity: 1 !important;
}

/* Slightly richer hover state for the whole chip. */
.select2-container .select2-selection--multiple .select2-selection__choice:hover,
.select2-selection__choice:hover {
    color: var(--vp-ink) !important;
    background: rgba(159, 191, 208, 0.36) !important;
    border-color: rgba(84, 44, 46, 0.52) !important;
    opacity: 1 !important;
    filter: none !important;
}

/* =========================================================
   CHECKBOXES + RADIO BUTTONS
   ========================================================= */

/* Keep SillyTavern's functional/icon-controlled checkboxes hidden. */
input[type="checkbox"].displayNone,
input[type="radio"].displayNone,
#rm_button_panel_pin {
    display: none !important;
}

/* Style only ordinary visible checkboxes and radio buttons. */
input[type="checkbox"]:not(.del_checkbox):not(.displayNone):not(#rm_button_panel_pin),
input[type="radio"]:not(.displayNone) {
    -webkit-appearance: none !important;
    appearance: none !important;

    display: inline-grid !important;
    place-content: center !important;
    flex: 0 0 auto !important;

    width: 1.15rem !important;
    height: 1.15rem !important;
    min-width: 1.15rem !important;
    min-height: 1.15rem !important;

    margin: 0 0.35rem 0 0 !important;
    padding: 0 !important;

    background: var(--vp-paper-light) !important;
    border: 1.5px solid var(--vp-ink) !important;
    border-radius: 4px !important;

    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.65),
        1px 2px 0 rgba(84, 44, 46, 0.13) !important;

    vertical-align: middle !important;
    cursor: pointer !important;

    opacity: 1 !important;
    filter: none !important;
}

/* Checkbox checkmark. */
input[type="checkbox"]:not(.del_checkbox):not(.displayNone):not(#rm_button_panel_pin)::before {
    content: "" !important;

    width: 0.32rem !important;
    height: 0.62rem !important;

    background: transparent !important;
    box-shadow: none !important;

    clip-path: none !important;
    -webkit-clip-path: none !important;

    border: solid var(--vp-ink) !important;
    border-width: 0 2px 2px 0 !important;

    transform: rotate(45deg) scale(0) !important;
    transform-origin: center !important;
    transition: transform 120ms ease !important;
}

input[type="checkbox"]:not(.del_checkbox):not(.displayNone):not(#rm_button_panel_pin):checked::before {
    transform: rotate(45deg) scale(1) !important;
}

/* Checked checkbox. */
input[type="checkbox"]:not(.del_checkbox):not(.displayNone):not(#rm_button_panel_pin):checked {
    background: var(--vp-yellow) !important;
}

/* Radio-button shape. */
input[type="radio"]:not(.displayNone) {
    border-radius: 50% !important;
}

input[type="radio"]:not(.displayNone)::before {
    content: "" !important;

    width: 0.52rem !important;
    height: 0.52rem !important;

    background: var(--vp-coral) !important;
    border-radius: 50% !important;

    transform: scale(0) !important;
    transition: transform 120ms ease !important;
}

input[type="radio"]:not(.displayNone):checked::before {
    transform: scale(1) !important;
}

/* Hover. */
input[type="checkbox"]:not(.del_checkbox):not(.displayNone):not(#rm_button_panel_pin):not(:disabled):hover,
input[type="radio"]:not(.displayNone):not(:disabled):hover {
    background: var(--vp-paper-2) !important;
    border-color: var(--vp-coral) !important;
}

/* Keep checked checkboxes yellow on hover. */
input[type="checkbox"]:not(.del_checkbox):not(.displayNone):not(#rm_button_panel_pin):checked:not(:disabled):hover {
    background: var(--vp-yellow) !important;
}

/* Keyboard focus. */
input[type="checkbox"]:not(.del_checkbox):not(.displayNone):not(#rm_button_panel_pin):focus-visible,
input[type="radio"]:not(.displayNone):focus-visible {
    outline: 3px solid rgba(234, 201, 85, 0.32) !important;
    outline-offset: 2px !important;
}

/* Disabled controls. */
input[type="checkbox"]:not(.del_checkbox):not(.displayNone):not(#rm_button_panel_pin):disabled,
input[type="radio"]:not(.displayNone):disabled {
    opacity: 0.45 !important;
    filter: saturate(0.4) !important;
    cursor: default !important;
}

/* =========================================================
   HIDE ICON-CONTROLLED SILLYTAVERN CHECKBOXES
   Keep this at the very end of the CSS.
   ========================================================= */

#rm_button_panel_pin_div > #rm_button_panel_pin,
#WI_panel_pin_div > #WI_panel_pin,
#lm_button_panel_pin_div > #lm_button_panel_pin,
label.menu_button > input[type="checkbox"].displayNone {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;

    position: absolute !important;
    width: 0 !important;
    height: 0 !important;
    min-width: 0 !important;
    min-height: 0 !important;

    margin: 0 !important;
    padding: 0 !important;
    border: 0 !important;
    box-shadow: none !important;

    pointer-events: none !important;
}

/* =========================================================
   BUTTONS
   ========================================================= */

.menu_button,
.buttons_block .menu_button,
.popup-button,
.popup-button-ok,
.popup-button-cancel,
button:not(.mes_button):not(.drawer-icon):not(.fa-solid):not([class*="icon"]):not(.sm-page-playlist-play):not(.wl-pl-tab),
input[type="button"],
input[type="submit"] {
    color: var(--vp-ink) !important;
    background: var(--vp-yellow) !important;
    border: 1.5px solid var(--vp-ink) !important;
    border-radius: 999px !important;
    box-shadow: 2px 3px 0 rgba(84, 44, 46, 0.2) !important;
    font-size: 0.74rem;
    font-weight: 800;
    letter-spacing: 0.055em;

    transition:
        transform 0.12s ease,
        box-shadow 0.12s ease,
        background-color 0.12s ease;
}

/* SillyTavern normally applies grayscale(0.5) to menu buttons until hover.
   Keep active buttons fully colored; disabled buttons retain their native muted state. */
.menu_button:not([disabled]):not(.disabled) {
    filter: none !important;
    opacity: 1 !important;
}

.menu_button:hover,
.buttons_block .menu_button:hover,
.popup-button:hover,
.popup-button-ok:hover,
.popup-button-cancel:hover,
button:not(.mes_button):not(.drawer-icon):not(.fa-solid):not([class*="icon"]):not(.sm-page-playlist-play):not(.wl-pl-tab):hover,
input[type="button"]:hover,
input[type="submit"]:hover {
    filter: none !important;
    transform: translate(-1px, -1px);
    box-shadow: 3px 4px 0 rgba(84, 44, 46, 0.21) !important;
}

.menu_button:active,
.popup-button:active,
button:not(.mes_button):not(.drawer-icon):not(.fa-solid):not([class*="icon"]):not(.sm-page-playlist-play):not(.wl-pl-tab):active {
    transform: translate(1px, 1px);
    box-shadow: 1px 1px 0 rgba(84, 44, 46, 0.18) !important;
}

.menu_button.redWarningBG,
.redWarningBG,
.danger_button {
    background: var(--vp-coral) !important;
}

.menu_button.greenBG,
.greenBG,
.success_button {
    background: var(--vp-green) !important;
}

.menu_button.secondary,
.popup-button-cancel {
    background: var(--vp-blue) !important;
}

/* Icon-only UI buttons stay compact and paper-like. */
.drawer-icon,
.mes_button,
.extraMesButtons > div,
#send_but,
#options_button,
#mes_continue,
#mes_stop,
#mes_impersonate,
#extensionsMenuButton {
    border-radius: 50% !important;
}

/* Message action buttons are fully visible normally. */
.mes_button,
.extraMesButtons > div {
    color: var(--vp-ink) !important;
    background: transparent !important;
    border: 0 !important;
    box-shadow: none !important;
    opacity: 1 !important;
    filter: none !important;

    transition:
        color 0.12s ease,
        opacity 0.12s ease,
        filter 0.12s ease,
        transform 0.12s ease;
}

/* Hover becomes slightly softer instead of stronger. */
.mes_button:hover,
.extraMesButtons > div:hover {
    color: var(--vp-ink-soft) !important;
    opacity: 0.82 !important;
    filter: saturate(0.78) !important;
    transform: rotate(-3deg);
}

/* Small pressed effect. */
.mes_button:active,
.extraMesButtons > div:active {
    color: var(--vp-ink) !important;
    opacity: 1 !important;
    filter: none !important;
    transform: scale(0.94);
}

/* Playlist play button should not receive the yellow pill-button styling. */
.sm-page-playlist-play,
.sm-page-playlist-play:hover,
.sm-page-playlist-play:active {
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    transform: none !important;
    padding: 0 !important;
}

} /* end main-UI control scope */

/* =========================================================
   CHAT + MESSAGE CARDS
   ========================================================= */

#chat {
    background: transparent !important;
    scrollbar-gutter: stable;
}

.mes {
    position: relative;
    margin: 10px 8px !important;
    padding: 15px 16px 16px !important;

    color: var(--vp-ink) !important;
    background:
        linear-gradient(transparent 96%, rgba(84, 44, 46, 0.055) 96%) 0 0 / 100% 1.72em,
        rgba(255, 250, 243, 0.91) !important;
    border: 1.5px solid var(--vp-line) !important;
    border-top: 7px solid var(--vp-blue) !important;
    border-radius: 9px !important;
    box-shadow: var(--vp-shadow-medium) !important;
}

.mes[is_user="true"],
.mes.user_mes {
    background:
        linear-gradient(transparent 96%, rgba(84, 44, 46, 0.055) 96%) 0 0 / 100% 1.72em,
        rgba(248, 239, 230, 0.94) !important;
    border-top-color: var(--vp-pink) !important;
}

.mes[is_system="true"],
.mes.system_mes {
    background: rgba(242, 231, 218, 0.9) !important;
    border-top-color: var(--vp-lilac) !important;
}

.mes::after {
    content: "";
    position: absolute;
    top: 12px;
    right: 13px;
    width: 25px;
    height: 7px;
    pointer-events: none;

    background:
        radial-gradient(ellipse at center, var(--vp-ink) 0 2px, transparent 2.5px) 0 0 / 8px 7px repeat-x;
    opacity: 0.14;
    transform: rotate(-4deg);
}

.mes .avatar,
.mesAvatarWrapper .avatar {
    border: 1.5px solid var(--vp-ink) !important;
    border-radius: 8px !important;
    box-shadow: 2px 3px 0 rgba(84, 44, 46, 0.16) !important;
    overflow: hidden;
}


.mes_text {
    color: var(--vp-ink) !important;
    font-family: var(--vp-serif);
    line-height: 1.62;
    text-wrap: pretty;
}

.mes_text code,
.mes_text pre,
code,
pre {
    color: var(--vp-ink) !important;
    background: rgba(159, 191, 208, 0.16) !important;
    border: 1px solid rgba(84, 44, 46, 0.18);
    border-radius: 6px;
    font-family: var(--vp-mono);
}

.mes_text code,
code {
    padding: 0.1em 0.34em;
}

.mes_text pre,
pre {
    padding: 0.8em 0.95em;
}

.mes_bias,
.mes_timer,
.tokenCounterDisplay,
.mesIDDisplay,
.timestamp {
    color: var(--vp-ink-soft) !important;
    font-family: var(--vp-mono);
    font-size: 0.68rem !important;
    letter-spacing: 0.04em;
    opacity: 0.7;
}

/* =========================================================
   SEND FORM
   ========================================================= */

#send_form {
    margin: 8px !important;
    padding: 8px !important;
    background:
        linear-gradient(90deg, rgba(234, 201, 85, 0.14), transparent 30%, rgba(223, 162, 189, 0.12)),
        rgba(248, 241, 232, 0.96) !important;
    border: 1.5px solid var(--vp-ink) !important;
    border-radius: 12px !important;
    box-shadow: 4px 5px 0 rgba(84, 44, 46, 0.15) !important;
}

#send_textarea {
    min-height: 44px;
    color: var(--vp-ink) !important;
    background:
        linear-gradient(transparent 94%, rgba(84, 44, 46, 0.1) 94%) 0 0 / 100% 1.7em,
        rgba(255, 250, 243, 0.78) !important;
    border: 0 !important;
    border-radius: 7px !important;
    box-shadow: none !important;
    font-family: var(--vp-serif);
    line-height: 1.55;
}

#send_but,
#options_button,
#mes_continue,
#mes_stop,
#mes_impersonate {
    color: var(--vp-ink) !important;
    background: transparent !important;
    border: 0 !important;
    box-shadow: none !important;
}

#send_but:hover,
#options_button:hover,
#mes_continue:hover,
#mes_stop:hover,
#mes_impersonate:hover {
    background: rgba(234, 201, 85, 0.25) !important;
}

/* =========================================================
   CHARACTERS, PERSONAS, FOLDERS + RECENT CHATS
   ========================================================= */

.character_select,
.bogus_folder_select,
.avatar-container,
.recentChat,
.persona-card {
    position: relative;
    color: var(--vp-ink) !important;
    background: rgba(255, 250, 243, 0.54) !important;
    border: 1.5px solid var(--vp-line) !important;
    border-radius: 9px !important;
    box-shadow: 2px 3px 0 rgba(84, 44, 46, 0.11) !important;
    transition: transform 0.15s ease, box-shadow 0.15s ease, background-color 0.15s ease !important;
}

.character_select:hover,
.bogus_folder_select:hover,
.avatar-container:hover,
.recentChat:hover,
.persona-card:hover {
    background: rgba(255, 250, 243, 0.83) !important;
    border-color: var(--vp-ink) !important;
    box-shadow: 3px 4px 0 rgba(84, 44, 46, 0.16) !important;
    transform: translateY(-1px) rotate(-0.15deg);
}

.character_select:nth-child(4n + 1),
.recentChat:nth-child(4n + 1) {
    border-top: 5px solid var(--vp-pink) !important;
}

.character_select:nth-child(4n + 2),
.recentChat:nth-child(4n + 2) {
    border-top: 5px solid var(--vp-blue) !important;
}

.character_select:nth-child(4n + 3),
.recentChat:nth-child(4n + 3) {
    border-top: 5px solid var(--vp-green) !important;
}

.character_select:nth-child(4n),
.recentChat:nth-child(4n) {
    border-top: 5px solid var(--vp-yellow) !important;
}

.character_select .avatar,
.avatar-container .avatar,
.persona-card .avatar {
    border: 1.5px solid var(--vp-ink) !important;
    border-radius: 8px !important;
    box-shadow: 2px 2px 0 rgba(84, 44, 46, 0.13);
}

.character_select.is_fav .avatar {
    outline: 3px solid var(--vp-yellow) !important;
    outline-offset: 2px;
}

.character_select.is_fav .ch_name,
.character_select.is_fav:hover .ch_name {
    color: var(--vp-ink) !important;
    text-decoration-color: var(--vp-yellow);
}

/* Right character drawer: strong color states and frameless rows. */

/* Character-drawer toolbar and icon controls: full color at rest. */
#right-nav-panel .right_menu_button,
#rm_characters_block .right_menu_button,
#rm_characters_topbar .right_menu_button {
    color: var(--vp-ink) !important;
    opacity: 1 !important;
    filter: none !important;
}

/* Hover should be the quieter state, not the more colorful state. */
#right-nav-panel .right_menu_button:hover,
#right-nav-panel .right_menu_button.active:hover,
#rm_characters_block .right_menu_button:hover,
#rm_characters_topbar .right_menu_button:hover {
    color: var(--vp-ink) !important;
    opacity: 0.88 !important;
    filter: brightness(0.94) saturate(0.82) !important;
}

/* Keep active drawer controls fully visible when not hovered. */
#right-nav-panel .right_menu_button.active,
#rm_characters_block .right_menu_button.active,
#rm_characters_topbar .right_menu_button.active {
    opacity: 1 !important;
    filter: none !important;
}

/* Character-list tags and their containing rows are not faded. */
#right-nav-panel #bulkTagsList,
#right-nav-panel #tagList .tag:not(.excluded),
#right-nav-panel #groupTagList .tag:not(.excluded),
#right-nav-panel .tags.tags_inline,
#right-nav-panel .rm_tag_filter .tag:not(.excluded) {
    opacity: 1 !important;
    filter: none !important;
}

/* Slightly mute ordinary tags only while hovering them. */
#right-nav-panel #tagList .tag:not(.selected):not(.excluded):hover,
#right-nav-panel #groupTagList .tag:not(.selected):not(.excluded):hover,
#right-nav-panel .rm_tag_filter .tag:not(.selected):not(.excluded):hover,
#right-nav-panel .tags.tags_inline .tag:not(.selected):not(.excluded):hover {
    opacity: 0.88 !important;
    filter: brightness(0.96) saturate(0.82) !important;
}

/* Selected tags remain fully colored and clearly active. */
#right-nav-panel .tag.selected,
#right-nav-panel .tag.selected:hover {
    opacity: 1 !important;
    filter: none !important;
}

/* Preserve the meaning of explicitly excluded tags. */
#right-nav-panel .tag.excluded,
#right-nav-panel .tag.excluded:hover {
    opacity: 1 !important;
    filter: saturate(0.4) !important;
}

/* Folder-assignment icon: colored when available, visibly subdued only
   when SillyTavern marks it as having no folder. */
#right-nav-panel .tag_as_folder.right_menu_button:not(.no_folder) {
    opacity: 1 !important;
    filter: none !important;
}

#right-nav-panel .tag_as_folder.right_menu_button:not(.no_folder):hover {
    opacity: 0.88 !important;
    filter: brightness(0.94) saturate(0.82) !important;
}

#right-nav-panel .tag_as_folder.right_menu_button.no_folder {
    opacity: 0.72 !important;
    filter: brightness(0.78) saturate(0.5) !important;
}

#rm_print_characters_block .character_select,
#rm_print_characters_block .group_select,
#rm_print_characters_block .bogus_folder_select,
#right-nav-panel .character_select,
#right-nav-panel .group_select,
#right-nav-panel .bogus_folder_select,
#right-nav-panel .avatar-container {
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    outline: none !important;
}

/* Keep navigation feedback without recreating a visible card frame. */
#rm_print_characters_block .character_select:hover,
#rm_print_characters_block .group_select:hover,
#rm_print_characters_block .bogus_folder_select:hover,
#right-nav-panel .character_select:hover,
#right-nav-panel .group_select:hover,
#right-nav-panel .bogus_folder_select:hover,
#right-nav-panel .avatar-container:hover {
    background: rgba(234, 201, 85, 0.11) !important;
    border: 0 !important;
    box-shadow: none !important;
    transform: none !important;
}

/* =========================================================
   TAGS
   ========================================================= */

.tag,
.tag_name {
    box-shadow: 1px 2px 0 rgba(84, 44, 46, 0.16);
    font-family: var(--vp-mono);
    font-size: 0.68rem !important;
    letter-spacing: 0.035em;
}

/* =========================================================
   WORLD INFO / LOREBOOK CARDS
   ========================================================= */

.world_entry {
    margin-bottom: 8px;
}

.world_entry .wi-card-entry {
    position: relative;
    overflow: hidden !important;
    color: var(--vp-ink) !important;
    background:
        linear-gradient(
            90deg,
            rgba(234, 201, 85, 0.15),
            transparent 46%,
            rgba(223, 162, 189, 0.12)
        ),
        linear-gradient(
            transparent 96%,
            rgba(84, 44, 46, 0.055) 96%
        ) 0 0 / 100% 1.72em,
        rgba(255, 250, 243, 0.72) !important;
    border: 1.5px solid var(--vp-ink) !important;
    border-radius: 8px !important;
    box-shadow: 3px 4px 0 rgba(84, 44, 46, 0.12) !important;
}

.world_entry .wi-card-entry::before {
    content: "";
    display: block;
    height: 7px;
    margin: 0 !important;
    background: linear-gradient(
        90deg,
        var(--vp-yellow),
        var(--vp-pink),
        var(--vp-blue),
        var(--vp-green)
    );
    border-bottom: 1px solid rgba(84, 44, 46, 0.28);
    border-radius: 0 !important;
}

.world_entry .wi-card-entry:hover {
    border-color: var(--vp-ink) !important;
    box-shadow: 4px 5px 0 rgba(84, 44, 46, 0.16) !important;
}

/* The nested drawer is structural; the outer lorebook card supplies the frame. */
.world_entry .wi-card-entry > .inline-drawer,
.world_entry .wi-card-entry > .inline-drawer > .inline-drawer-header {
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
}

.world_entry .wi-card-entry > .inline-drawer > .inline-drawer-content {
    background: rgba(255, 250, 243, 0.34) !important;
    border: 0 !important;
    border-top: 1px dashed var(--vp-line-soft) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
}

.WIEntryTitleAndStatus textarea.text_pole {
    color: var(--vp-ink) !important;
    background: transparent !important;
    border: 0 !important;
    border-bottom: 1px solid var(--vp-line-soft) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    font-family: var(--vp-serif);
    font-size: 0.94rem;
    font-weight: 700;
}

.WIEntryTitleAndStatus textarea.text_pole:focus {
    border-bottom-color: var(--vp-coral) !important;
}

/* =========================================================
   REASONING BLOCK
   ========================================================= */

.mes_reasoning_header {
    color: var(--vp-ink) !important;
    background:
        linear-gradient(90deg, rgba(181, 155, 216, 0.22), rgba(255, 255, 255, 0.18)) !important;
    border: 1.5px solid var(--vp-line) !important;
    border-radius: 8px !important;
    box-shadow: 2px 3px 0 rgba(84, 44, 46, 0.11);
    font-family: var(--vp-mono);
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: 0.075em;
    text-transform: uppercase;
    padding: 7px 14px;
}

.mes_reasoning {
    color: var(--vp-ink-soft) !important;
    background:
        linear-gradient(90deg, transparent 27px, rgba(220, 122, 122, 0.23) 28px, transparent 29px),
        repeating-linear-gradient(180deg, rgba(255, 255, 255, 0.3) 0, rgba(255, 255, 255, 0.3) 26px, rgba(84, 44, 46, 0.09) 27px, rgba(255, 255, 255, 0.3) 28px) !important;
    border: 1.5px solid var(--vp-line) !important;
    border-top: 0 !important;
    border-radius: 0 0 8px 8px !important;
    padding: 12px 14px 12px 41px;
    font-family: var(--vp-mono);
    font-size: 0.86em;
    line-height: 1.52;
}

.mes_reasoning_header + .mes_reasoning {
    margin-top: -1px;
}

.mes_reasoning code {
    background: rgba(181, 155, 216, 0.14) !important;
}

/* =========================================================
   POPUPS + MENUS
   ========================================================= */

.popup[open],
.popup,
.dialogue_popup {
    color: var(--vp-ink) !important;
    background:
        radial-gradient(circle at 15% 18%, rgba(223, 162, 189, 0.09) 0 1px, transparent 1.5px) 0 0 / 15px 15px,
        var(--vp-paper) !important;
    border: 1.5px solid rgba(84, 44, 46, 0.7) !important;
    border-radius: 12px !important;
    box-shadow:
        var(--vp-shadow-float),
        inset 0 0 0 4px rgba(255, 255, 255, 0.28) !important;
}

.popup-title,
.popup h3,
.dialogue_popup h3 {
    color: var(--vp-ink) !important;
    font-family: var(--vp-serif);
    font-style: italic;
    text-decoration: underline;
    text-decoration-color: rgba(234, 201, 85, 0.75);
    text-decoration-thickness: 6px;
    text-underline-offset: -3px;
    text-decoration-skip-ink: none;
}

.popup-controls {
    background: transparent !important;
    border-top: 1px solid var(--vp-line-soft) !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
}

.list-group,
.options-content,
.context-menu,
.ui-menu,
#floatingPrompt,
#slashCommandBrowser {
    color: var(--vp-ink) !important;
    background: rgba(248, 241, 232, 0.98) !important;
    border: 1.5px solid var(--vp-ink) !important;
    border-radius: 8px !important;
    box-shadow: var(--vp-shadow-float) !important;
}

.list-group-item,
.context-menu-item,
.ui-menu-item {
    border-bottom: 1px dashed var(--vp-line-soft);
}

.list-group-item:hover,
.context-menu-item:hover,
.ui-menu-item:hover {
    background: rgba(234, 201, 85, 0.22) !important;
}

/* The specialized relationship-analysis popup has its own stronger rules. */
.popup:has(.relationship-analysis) {
    font-family: var(--vp-serif);
}

/* Keep the SillyTavern initializing/loading screen transparent. */
.popup:has(#loader),
.popup:has(.splash-screen),
.popup-content:has(#loader),
.popup-content:has(.splash-screen),
#loader.splash-screen {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
    border: 0 !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
}

/* Menu links remain strong at rest; hover is the quieter state. */

/* Text links inside drawers, popups, menus, and option lists. */
#left-nav-panel :is(a, .link, .textLink, .text_link, [role="link"]),
#right-nav-panel :is(a, .link, .textLink, .text_link, [role="link"]),
.popup :is(a, .link, .textLink, .text_link, [role="link"]),
.dialogue_popup :is(a, .link, .textLink, .text_link, [role="link"]),
.options-content :is(a, .link, .textLink, .text_link, [role="link"]),
.context-menu :is(a, .link, .textLink, .text_link, [role="link"]),
.list-group :is(a, .link, .textLink, .text_link, [role="link"]),
.ui-menu :is(a, .link, .textLink, .text_link, [role="link"]) {
    color: var(--vp-ink) !important;
    opacity: 1 !important;
    filter: none !important;
    text-decoration-color: rgba(84, 44, 46, 0.46) !important;
    transition:
        color 0.12s ease,
        opacity 0.12s ease,
        filter 0.12s ease,
        text-decoration-color 0.12s ease !important;
}

/* Text-based menu rows that are not necessarily anchor elements. */
.list-group-item,
.context-menu-item,
.ui-menu-item,
.options-content [role="menuitem"],
.popup [role="menuitem"],
.dialogue_popup [role="menuitem"] {
    color: var(--vp-ink) !important;
    opacity: 1 !important;
    filter: none !important;
}

/* Hover is intentionally the quieter state. Existing hover backgrounds
   still provide a clear interaction cue. */
#left-nav-panel :is(a, .link, .textLink, .text_link, [role="link"]):hover,
#right-nav-panel :is(a, .link, .textLink, .text_link, [role="link"]):hover,
.popup :is(a, .link, .textLink, .text_link, [role="link"]):hover,
.dialogue_popup :is(a, .link, .textLink, .text_link, [role="link"]):hover,
.options-content :is(a, .link, .textLink, .text_link, [role="link"]):hover,
.context-menu :is(a, .link, .textLink, .text_link, [role="link"]):hover,
.list-group :is(a, .link, .textLink, .text_link, [role="link"]):hover,
.ui-menu :is(a, .link, .textLink, .text_link, [role="link"]):hover,
.list-group-item:hover,
.context-menu-item:hover,
.ui-menu-item:hover,
.options-content [role="menuitem"]:hover,
.popup [role="menuitem"]:hover,
.dialogue_popup [role="menuitem"]:hover {
    color: var(--vp-ink-soft) !important;
    opacity: 0.84 !important;
    filter: saturate(0.72) !important;
    text-decoration-color: rgba(85, 126, 143, 0.5) !important;
}

/* Active/current choices should remain strong even when hovered. */
#left-nav-panel :is(a, .link, .textLink, .text_link, [role="link"]).active,
#right-nav-panel :is(a, .link, .textLink, .text_link, [role="link"]).active,
.popup :is(a, .link, .textLink, .text_link, [role="link"]).active,
.dialogue_popup :is(a, .link, .textLink, .text_link, [role="link"]).active,
.list-group-item.active,
.context-menu-item.active,
.ui-menu-item.active,
[role="menuitem"][aria-current="true"],
[role="menuitem"][aria-selected="true"] {
    color: var(--vp-ink) !important;
    opacity: 1 !important;
    filter: none !important;
}

/* Preserve genuinely disabled states. */
#left-nav-panel :is(a, .link, .textLink, .text_link, [role="link"]):is(.disabled, [disabled], [aria-disabled="true"]),
#right-nav-panel :is(a, .link, .textLink, .text_link, [role="link"]):is(.disabled, [disabled], [aria-disabled="true"]),
.popup :is(a, .link, .textLink, .text_link, [role="link"]):is(.disabled, [disabled], [aria-disabled="true"]),
.dialogue_popup :is(a, .link, .textLink, .text_link, [role="link"]):is(.disabled, [disabled], [aria-disabled="true"]),
.list-group-item:is(.disabled, [aria-disabled="true"]),
.context-menu-item:is(.disabled, [aria-disabled="true"]),
.ui-menu-item:is(.disabled, [aria-disabled="true"]),
[role="menuitem"][aria-disabled="true"] {
    color: var(--vp-ink-soft) !important;
    opacity: 0.48 !important;
    filter: saturate(0.35) !important;
    cursor: default !important;
}

/* =========================================================
   TOASTS
   ========================================================= */

.toast {
    position: relative;
    overflow: hidden;
    color: var(--vp-ink) !important;
    background:
        linear-gradient(transparent 94%, rgba(84, 44, 46, 0.07) 94%) 0 0 / 100% 1.55em,
        rgba(255, 250, 243, 0.98) !important;
    border: 1.5px solid var(--vp-ink) !important;
    border-left: 8px solid var(--vp-blue) !important;
    border-radius: 8px !important;
    padding: 11px 13px !important;
    box-shadow: 4px 5px 0 rgba(84, 44, 46, 0.18) !important;
    opacity: 1 !important;
}

.toast::after {
    content: "";
    position: absolute;
    top: 9px;
    right: 10px;
    width: 28px;
    height: 7px;
    background: radial-gradient(ellipse at center, var(--vp-ink) 0 2px, transparent 2.5px) 0 0 / 9px 7px repeat-x;
    opacity: 0.15;
    transform: rotate(-4deg);
}

.toast-title {
    color: var(--vp-ink) !important;
    margin: 0 0 6px !important;
    padding: 0 0 6px !important;
    border-bottom: 1px dashed var(--vp-line) !important;
    font-family: var(--vp-mono);
    font-size: 0.72rem !important;
    font-weight: 900 !important;
    letter-spacing: 0.08em !important;
    text-transform: uppercase !important;
}

.toast-message {
    color: var(--vp-ink-soft) !important;
    font-family: var(--vp-serif);
    font-size: 0.92rem !important;
    line-height: 1.42 !important;
}

.toast.toast-success {
    border-left-color: var(--vp-green) !important;
}

.toast.toast-warning {
    border-left-color: var(--vp-yellow) !important;
}

.toast.toast-error {
    border-left-color: var(--vp-coral) !important;
}

.toast.toast-info {
    border-left-color: var(--vp-blue) !important;
}

/* =========================================================
   QUICK REPLIES + SMALL TOOLBARS
   ========================================================= */

#qr--bar > .qr--buttons.qr--color,
.qr--buttons,
.quick-reply-button {
    color: var(--vp-ink) !important;
    background: rgba(255, 250, 243, 0.55) !important;
    border: 1.5px solid var(--vp-line) !important;
    border-radius: 999px !important;
    box-shadow: 1px 2px 0 rgba(84, 44, 46, 0.13);
    font-family: var(--vp-mono);
    font-size: 0.7rem;
}

#qr--bar > .qr--buttons.qr--color:hover,
.qr--buttons:hover,
.quick-reply-button:hover {
    background: var(--vp-yellow) !important;
    border-color: var(--vp-ink) !important;
}

/* =========================================================
   SCROLLBARS
   ========================================================= */

@-moz-document url-prefix() {
    * {
        scrollbar-width: thin;
        scrollbar-color: var(--vp-pink) var(--vp-paper-2);
    }
}

::-webkit-scrollbar {
    width: 9px;
    height: 9px;
    background: transparent;
}

::-webkit-scrollbar-track {
    background: var(--vp-paper-2);
    border-left: 1px solid var(--vp-line-soft);
}

::-webkit-scrollbar-thumb {
    background: var(--vp-pink);
    border: 2px solid var(--vp-paper-2);
    border-radius: 999px;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--vp-coral);
}

::-webkit-scrollbar-button,
::-webkit-scrollbar-corner {
    display: none;
    background: transparent;
}

