/* Shared icon behavior */
#leftNavDrawerIcon::before,
#API-status-top.fa-plug-circle-exclamation::before,
#API-status-top.fa-plug::before,
.drawer-icon[title="AI Response Formatting"]::before,
#WIDrawerIcon::before,
.drawer-icon[title="User Settings"]::before,
#backgrounds-drawer-toggle .drawer-icon::before,
.drawer-icon[title="Extensions"]::before,
.drawer-icon[title="Persona Management"]::before,
#rightNavDrawerIcon::before,
#options_button::before,
#extensionsMenuButton::before,
#group_member_picker_button::before,
#mes_impersonate::before,
#mes_continue::before,
#send_but::before {
    content: "" !important;
    display: block;
    width: var(--craft-icon-size);
    height: var(--craft-icon-size);
    margin: auto;
    background-color: currentColor;
    -webkit-mask-image: var(--craft-mask);
    mask-image: var(--craft-mask);
    -webkit-mask-size: contain;
    mask-size: contain;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-position: center;
    mask-position: center;

    /* Full color at rest; hover becomes slightly softer instead. */
    opacity: 1 !important;
    filter: drop-shadow(0 1px 0 var(--craft-icon-shadow)) !important;
    transform-origin: center;
    transition:
        transform 150ms ease,
        opacity 150ms ease;
}

