/* =========================================================
   CHARACTER DRAWER — OVERSIZED POSTAGE STAMP ROWS
   hide name, stamp-shaped avatar, custom highlight
   ========================================================= */

/* ---------- shared row ---------- */

#rm_print_characters_block .character_select,
#right-nav-panel .character_select {
    position: relative;
    display: flex !important;
    align-items: flex-start !important;
    gap: 12px;
    padding: 10px 10px 10px 8px !important;
    border-radius: 16px !important;
    overflow: visible !important;
    background: transparent !important;
    border: 0 !important;
    box-shadow: none !important;
    transition:
        transform 0.15s ease,
        background-color 0.15s ease;
}

/* keep contents above decorative layers */
#rm_print_characters_block .character_select > *,
#right-nav-panel .character_select > * {
    position: relative;
    z-index: 2;
}

/* soft hover/active swash behind row */
#rm_print_characters_block .character_select::before,
#right-nav-panel .character_select::before {
    content: "";
    position: absolute;
    left: 2px;
    right: 6px;
    top: 4px;
    bottom: 4px;
    border-radius: 14px;
    opacity: 0;
    pointer-events: none;
    z-index: 0;

    background:
        linear-gradient(
            90deg,
            rgba(234, 201, 85, 0.18) 0%,
            rgba(234, 201, 85, 0.10) 18%,
            rgba(223, 162, 189, 0.12) 48%,
            rgba(159, 191, 208, 0.10) 100%
        );

    transform: rotate(-0.5deg) scale(0.985);
    transition:
        opacity 0.15s ease,
        transform 0.15s ease;
}

/* a couple faint "postal cancellation" lines */
#rm_print_characters_block .character_select::after,
#right-nav-panel .character_select::after {
    content: "";
    position: absolute;
    left: 48px;
    right: 20px;
    top: 16px;
    height: 24px;
    opacity: 0;
    pointer-events: none;
    z-index: 1;

    background:
        repeating-linear-gradient(
            -8deg,
            rgba(84, 44, 46, 0.00) 0 8px,
            rgba(84, 44, 46, 0.08) 8px 10px,
            rgba(84, 44, 46, 0.00) 10px 18px
        );

    transition: opacity 0.15s ease;
}

#rm_print_characters_block .character_select:hover::before,
#rm_print_characters_block .character_select:focus-within::before,
#right-nav-panel .character_select:hover::before,
#right-nav-panel .character_select:focus-within::before {
    opacity: 1;
    transform: rotate(0deg) scale(1);
}

#rm_print_characters_block .character_select:hover::after,
#rm_print_characters_block .character_select:focus-within::after,
#right-nav-panel .character_select:hover::after,
#right-nav-panel .character_select:focus-within::after {
    opacity: 1;
}

#rm_print_characters_block .character_select:hover,
#rm_print_characters_block .character_select:focus-within,
#right-nav-panel .character_select:hover,
#right-nav-panel .character_select:focus-within {
    background: transparent !important;
    transform: translateY(-1px);
}

/* ---------- avatar as oversized faux stamp ---------- */

