#right-nav-panel .character_select .avatar {
    position: relative;
    width: 68px !important;
    min-width: 68px !important;
    height: 68px !important;
    margin-top: 1px;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
