        100% 8%, 96% 18%, 100% 28%, 96% 38%, 100% 50%, 96% 62%, 100% 72%, 96% 82%, 100% 92%,
        92% 100%, 82% 96%, 72% 100%, 62% 96%, 50% 100%, 38% 96%, 28% 100%, 18% 96%, 8% 100%,
        0% 92%, 4% 82%, 0% 72%, 4% 62%, 0% 50%, 4% 38%, 0% 28%, 4% 18%, 0% 8%
    );
}

/* actual image */
