    box-shadow: none !important;

    font-size: 15px !important;
    line-height: 1 !important;
    text-align: center !important;

    /* Light paper edge around the star */
    text-shadow:
        -1px -1px 0 var(--vp-paper-light, #fff8ed),
         1px -1px 0 var(--vp-paper-light, #fff8ed),
        -1px  1px 0 var(--vp-paper-light, #fff8ed),
         1px  1px 0 var(--vp-paper-light, #fff8ed),
         2px  2px 0 rgba(84, 44, 46, 0.18) !important;

    filter: none !important;

    transform:
        translateX(-50%)
        rotate(10deg);

    pointer-events: none;

    transition:
        transform 0.16s ease,
        color 0.16s ease;
}

/* Little extra sparkle beside the main star */
#rm_print_characters_block .character_select.is_fav .ch_fav_icon::after,
#right-nav-panel .character_select.is_fav .ch_fav_icon::after {
    content: "✦";

    position: absolute;
    top: -7px;
    right: -5px;

    color: var(--fav-stamp-color);

    font-family: serif;
    font-size: 8px;
    line-height: 1;

    text-shadow:
        -15px 15px 0 color-mix(
            in srgb,
            var(--fav-stamp-color) 70%,
            var(--vp-yellow, #eac955) 30%
        );

    transform: rotate(-12deg);
}

/* Cute little movement on hover */
#rm_print_characters_block .character_select.is_fav:hover .ch_fav_icon,
#right-nav-panel .character_select.is_fav:hover .ch_fav_icon {
    transform:
        translateX(-50%)
        translateY(-1px)
        rotate(-5deg)
        scale(1.08);
}

/* ---------- mobile ---------- */

@media screen and (max-width: 800px) {
    #rm_print_characters_block .character_select.is_fav,
    #right-nav-panel .character_select.is_fav {
        --fav-avatar-size: 58px;
    }

    #rm_print_characters_block .character_select.is_fav .ch_fav_icon,
    #right-nav-panel .character_select.is_fav .ch_fav_icon {
        top: -6px;

        width: 16px !important;
        height: 16px !important;

        font-size: 14px !important;
    }
}

/* =========================================================
   HOTSWAP CHARACTER CAROUSEL
   Compact scrapbook photo cards
   ========================================================= */

#HotSwapWrapper {
    --hotswap-photo-size: 54px;

    position: relative !important;

    width: 100% !important;
    height: auto !important;
    min-height: 0 !important;
    max-height: none !important;

    margin: 1px auto !important;
    padding: 0 !important;
    box-sizing: border-box !important;

    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;

    overflow: visible !important;
}

/* Remove any decorative wrapper pieces from older versions */

#HotSwapWrapper::before,
#HotSwapWrapper::after {
    content: none !important;
    display: none !important;
}

/* =========================================================
   CAROUSEL ROW
   ========================================================= */

#HotSwapWrapper .hotswap.avatars_inline,
#HotSwapWrapper .hotswap.avatars_inline.expander {
    position: relative !important;

    display: flex !important;
    align-items: center !important;
    justify-content: flex-start !important;

    gap: 8px !important;

    width: 100% !important;
    min-width: 0 !important;
    max-width: 100% !important;

    height: auto !important;
    min-height: calc(var(--hotswap-photo-size) + 20px) !important;
    max-height: none !important;

    margin: 0 !important;
    padding: 5px 3px 6px !important;
    box-sizing: border-box !important;

    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;

    overflow-x: auto !important;
    overflow-y: hidden !important;

    scrollbar-width: none !important;
    scroll-padding-inline: 3px;
}

#HotSwapWrapper .hotswap.avatars_inline::-webkit-scrollbar {
    display: none !important;
}

/* =========================================================
   INDIVIDUAL PHOTO CARDS
   ========================================================= */

#HotSwapWrapper .avatar.inline_avatar.character_select {
    --hotswap-accent: var(--vp-pink);

    position: relative !important;
    isolation: isolate;

    display: flex !important;
    align-items: flex-start !important;
    justify-content: center !important;

    flex: 0 0 auto !important;

    width: calc(var(--hotswap-photo-size) + 10px) !important;
    min-width: calc(var(--hotswap-photo-size) + 10px) !important;
    max-width: calc(var(--hotswap-photo-size) + 10px) !important;

    height: calc(var(--hotswap-photo-size) + 15px) !important;
    min-height: calc(var(--hotswap-photo-size) + 15px) !important;
    max-height: calc(var(--hotswap-photo-size) + 15px) !important;

    aspect-ratio: auto !important;

    margin: 0 !important;
    padding: 4px 4px 9px !important;
    box-sizing: border-box !important;

    color: var(--vp-ink) !important;
    background: var(--vp-paper-light) !important;

    border: 1px solid rgba(84, 44, 46, 0.58) !important;
    border-radius: 3px !important;

    outline: none !important;

    box-shadow:
        2px 3px 0 color-mix(
            in srgb,
            var(--hotswap-accent) 44%,
            rgba(84, 44, 46, 0.13)
        ) !important;

    overflow: visible !important;

    clip-path: none !important;
    -webkit-clip-path: none !important;

    filter: none !important;
    opacity: 1 !important;

    transform: rotate(-1.4deg);
    transform-origin: center center;

    transition:
        transform 140ms ease,
        box-shadow 140ms ease,
        background-color 140ms ease,
        border-color 140ms ease !important;
}

/* Override the normal character-card colored top borders */

#HotSwapWrapper .avatar.inline_avatar.character_select:nth-child(4n + 1),
#HotSwapWrapper .avatar.inline_avatar.character_select:nth-child(4n + 2),
#HotSwapWrapper .avatar.inline_avatar.character_select:nth-child(4n + 3),
#HotSwapWrapper .avatar.inline_avatar.character_select:nth-child(4n) {
    border-top: 1px solid rgba(84, 44, 46, 0.58) !important;
}

/* Alternating accent colors and tiny rotations */

#HotSwapWrapper .character_select:nth-child(5n + 1) {
    --hotswap-accent: var(--vp-pink);
    transform: rotate(-1.4deg);
}

#HotSwapWrapper .character_select:nth-child(5n + 2) {
    --hotswap-accent: var(--vp-blue);
    transform: rotate(1.2deg);
}

#HotSwapWrapper .character_select:nth-child(5n + 3) {
    --hotswap-accent: var(--vp-green);
    transform: rotate(-0.7deg);
}

#HotSwapWrapper .character_select:nth-child(5n + 4) {
    --hotswap-accent: var(--vp-yellow);
    transform: rotate(1.5deg);
}

#HotSwapWrapper .character_select:nth-child(5n) {
    --hotswap-accent: var(--vp-lilac);
    transform: rotate(-1deg);
}

/* Remove any tape left over from the earlier version */

#HotSwapWrapper .avatar.inline_avatar.character_select::before {
    content: none !important;
    display: none !important;
}

/* Tiny sparkle in the Polaroid-style bottom edge */

#HotSwapWrapper .avatar.inline_avatar.character_select::after {
    content: "✦";

    position: absolute;
    z-index: 5;

    right: 3px;
    bottom: 0;

    color: var(--hotswap-accent);

    font-family: Georgia, "Times New Roman", serif;
    font-size: 0.64rem;
    line-height: 1;

    text-shadow: 1px 1px 0 rgba(84, 44, 46, 0.12);

    pointer-events: none;
}

/* =========================================================
   CHARACTER IMAGE
   ========================================================= */

#HotSwapWrapper .avatar.inline_avatar.character_select > img {
    position: relative !important;
    inset: auto !important;
    z-index: 2;

    display: block !important;
    flex: 0 0 auto !important;

    width: var(--hotswap-photo-size) !important;
    min-width: var(--hotswap-photo-size) !important;
    max-width: var(--hotswap-photo-size) !important;

    height: var(--hotswap-photo-size) !important;
    min-height: var(--hotswap-photo-size) !important;
    max-height: var(--hotswap-photo-size) !important;

    aspect-ratio: 1 / 1 !important;

    margin: 0 !important;
    padding: 0 !important;
    box-sizing: border-box !important;

    object-fit: contain !important;
    object-position: center center !important;

    background:
        linear-gradient(
            135deg,
            rgba(223, 162, 189, 0.07),
            rgba(159, 191, 208, 0.08)
        ),
        var(--vp-paper) !important;

    border: 1px solid rgba(84, 44, 46, 0.34) !important;
    border-radius: 1px !important;

    outline: none !important;
    box-shadow: none !important;

    overflow: hidden !important;

    clip-path: none !important;
    -webkit-clip-path: none !important;

    transform: none !important;
    scale: 1 !important;

    filter: none !important;
    opacity: 1 !important;
}

/* =========================================================
   HOVER / FOCUS
   No scaling or lifting, so nothing gets clipped.
   ========================================================= */

#HotSwapWrapper .avatar.inline_avatar.character_select:hover,
#HotSwapWrapper .avatar.inline_avatar.character_select:focus-visible {
    color: var(--vp-ink) !important;
    background: #fffdf8 !important;

    border: 1px solid var(--vp-ink) !important;
    border-top: 1px solid var(--vp-ink) !important;

    outline: none !important;

    box-shadow:
        3px 4px 0 color-mix(
            in srgb,
            var(--hotswap-accent) 55%,
            rgba(84, 44, 46, 0.15)
        ) !important;

    transform: rotate(0deg) !important;

    filter: none !important;
    opacity: 1 !important;
}

#HotSwapWrapper .avatar.inline_avatar.character_select:hover > img,
#HotSwapWrapper .avatar.inline_avatar.character_select:focus-visible > img {
    object-fit: contain !important;
    object-position: center center !important;

    transform: none !important;
    scale: 1 !important;

    filter: none !important;
    opacity: 1 !important;
}

#HotSwapWrapper .avatar.inline_avatar.character_select:active {
    transform: rotate(0deg) translateY(1px) !important;

    box-shadow:
        1px 2px 0 color-mix(
            in srgb,
            var(--hotswap-accent) 44%,
            rgba(84, 44, 46, 0.13)
        ) !important;
}

/* =========================================================
   SMALL SCREENS
   ========================================================= */

@media screen and (max-width: 600px) {
    #HotSwapWrapper {
        --hotswap-photo-size: 49px;
    }

    #HotSwapWrapper .hotswap.avatars_inline,
    #HotSwapWrapper .hotswap.avatars_inline.expander {
        gap: 7px !important;
        padding: 4px 2px 5px !important;
    }
}
